+package org.apache.flink.table.runtime.functions.scalar;
+
+import org.apache.flink.annotation.Internal;
+import org.apache.flink.table.functions.BuiltInFunctionDefinitions;
+import org.apache.flink.table.functions.SpecializedFunction.SpecializedContext;
+
+import javax.annotation.Nullable;
+
+/** Implementation of {@link BuiltInFunctionDefinitions#CBRT}. */
+@Internal
+public final class CbrtFunction extends BuiltInScalarFunction {
+
+    public CbrtFunction(SpecializedContext context) {
+        super(BuiltInFunctionDefinitions.CBRT, context);
+    }
+
+    public @Nullable Double eval(@Nullable Double value) {
+        if (value == null) {
+            return null;
+        }
+        return Math.cbrt(value);
+    }
+}
